// Extract reply text (strip quoted content)
const fullText = $input.item.json.text || $input.item.json.snippet || '';

// Remove quoted replies (lines starting with >)
const lines = fullText.split('\n');
const replyLines = [];
for (const line of lines) {
  // Stop at quoted content markers
  if (line.trim().startsWith('>')) break;
  if (line.match(/^On .+ wrote:$/)) break;
  if (line.match(/^-{3,}\s*Original Message/i)) break;
  if (line.match(/^From:/i) && replyLines.length > 0) break;
  replyLines.push(line);
}

const replyText = replyLines.join('\n').trim();

// Extract price from reply — look for EUR amounts
const pricePatterns = [
  /€\s*(\d+[.,]?\d*)/,
  /(\d+[.,]?\d*)\s*€/,
  /(\d+[.,]?\d*)\s*eur/i,
  /price[:\s]+(\d+[.,]?\d*)/i,
  /cijena[:\s]+(\d+[.,]?\d*)/i,
  /cena[:\s]+(\d+[.,]?\d*)/i,
  /prezzo[:\s]+(\d+[.,]?\d*)/i,
  /prix[:\s]+(\d+[.,]?\d*)/i,
  /precio[:\s]+(\d+[.,]?\d*)/i,
  /preis[:\s]+(\d+[.,]?\d*)/i,
];

let price = null;
for (const pattern of pricePatterns) {
  const match = replyText.match(pattern);
  if (match) {
    price = parseFloat(match[1].replace(',', '.'));
    break;
  }
}

// If no labeled price found, try standalone number (if reply is short)
if (!price && replyText.length < 100) {
  const numMatch = replyText.match(/(\d{2,4}(?:[.,]\d{1,2})?)/);
  if (numMatch) {
    price = parseFloat(numMatch[1].replace(',', '.'));
  }
}

// Extract bookingId from the original email thread
// Look for quote-respond URL in the thread
const html = $input.item.json.html || $input.item.json.text || '';
const bookingIdMatch = html.match(/bookingId=([a-f0-9-]{36})/i);
const bookingId = bookingIdMatch ? bookingIdMatch[1] : null;

// Check for decline keywords
const declineKeywords = /\b(decline|reject|no|nein|non|ne|nem|nie|hayır|rifiut|rechaz|odmit|odbi|elutasit)\b/i;
const isDecline = !price && declineKeywords.test(replyText);

return {
  json: {
    replyText,
    price,
    bookingId,
    isDecline,
    senderEmail: $input.item.json.from?.value?.[0]?.address || $input.item.json.from,
    subject: $input.item.json.subject,
    threadId: $input.item.json.threadId || $input.item.json.id
  }
};

